import { warpedSourceTime, type AudioWarpPoint } from "./song-beat-map.ts";

type ReadPcm = (sourceSeconds: number, frames: number, left: Float32Array, right: Float32Array, signal?: AbortSignal) => Promise<void>;

/** Bounded-memory stereo-linked WSOLA. Samples inside grains play at their
 * original rate; correlated overlap-add moves grains to change duration.
 * Stereo uses one common offset (never independent channel phase searches).
 * Previewed sync assets and export are generated by this exact worker path. */
export class PcmStretchReader {
  private readonly hop = 1024;
  private readonly search = 256;
  private frame = 0;
  private cursor = 1024;
  private previous: [Float32Array, Float32Array] | null = null;
  private readonly output = [new Float32Array(1024), new Float32Array(1024)];
  private readonly candidates = [new Float32Array(2560), new Float32Array(2560)];
  private readonly read: ReadPcm;
  private readonly sampleRate: number;
  private readonly sourceStart: number;
  private readonly rate: number;
  private readonly warp?: AudioWarpPoint[];
  constructor(read: ReadPcm, sampleRate: number, sourceStart: number, rate: number, warp?: AudioWarpPoint[]) {
    this.read = read; this.sampleRate = sampleRate; this.sourceStart = sourceStart; this.rate = rate; this.warp = warp;
    if (!(rate >= .5 && rate <= 2)) throw new Error("Pitch-preserving stretch supports ½×–2× rates.");
    if (warp && (warp.length < 2 || warp.some((p, i) => !Number.isFinite(p.time) || !Number.isFinite(p.sourceTime) || (i > 0 && (p.time <= warp[i - 1].time || p.sourceTime <= warp[i - 1].sourceTime))))) throw new Error("Invalid audio warp map.");
  }
  private async next(signal?: AbortSignal) {
    signal?.throwIfAborted();
    const time = this.frame / this.sampleRate;
    const source = this.warp ? warpedSourceTime(this.warp, time) : this.sourceStart + time * this.rate;
    const pad = this.previous ? this.search : 0;
    await this.read(source - pad / this.sampleRate, this.hop * 2 + pad * 2, this.candidates[0], this.candidates[1], signal);
    let best = pad;
    if (this.previous) {
      const score = (offset: number) => {
        let dot = 0, power = 1e-12, reference = 1e-12;
        for (let i = 0; i < this.hop; i += 8) {
          for (let channel = 0; channel < 2; channel++) {
            const a = this.previous![channel][this.hop + i], b = this.candidates[channel][offset + i];
            dot += a * b; power += b * b; reference += a * a;
          }
        }
        // Silence chooses the expected position; ties prefer minimal jitter.
        return dot / Math.sqrt(power * reference) - Math.abs(offset - pad) * 1e-6;
      };
      let maximum = -Infinity;
      for (let offset = 0; offset <= pad * 2; offset += 8) { const value = score(offset); if (value > maximum) { maximum = value; best = offset; } }
      const coarse = best;
      for (let offset = Math.max(0, coarse - 7); offset <= Math.min(pad * 2, coarse + 7); offset++) { const value = score(offset); if (value > maximum) { maximum = value; best = offset; } }
    }
    const grain: [Float32Array, Float32Array] = [this.candidates[0].slice(best, best + this.hop * 2), this.candidates[1].slice(best, best + this.hop * 2)];
    for (let i = 0; i < this.hop; i++) {
      const weight = .5 - .5 * Math.cos(Math.PI * i / this.hop);
      for (let channel = 0; channel < 2; channel++) this.output[channel][i] = this.previous
        ? this.previous[channel][this.hop + i] * (1 - weight) + grain[channel][i] * weight
        : grain[channel][i];
    }
    this.previous = grain; this.frame += this.hop; this.cursor = 0;
  }
  async fill(frames: number, left: Float32Array, right: Float32Array, signal?: AbortSignal) {
    let written = 0;
    while (written < frames) {
      if (this.cursor === this.hop) await this.next(signal);
      const count = Math.min(frames - written, this.hop - this.cursor);
      left.set(this.output[0].subarray(this.cursor, this.cursor + count), written);
      right.set(this.output[1].subarray(this.cursor, this.cursor + count), written);
      this.cursor += count; written += count;
    }
  }
}
